function testPlantsThatFit() {
  console.log(plantsThatFit(32, 12))
  console.log(plantsThatFit(24, 18))
  console.log(plantsThatFit(48, 0))
}

function plantsThatFit(bedSize, spacingInches) {
  if (bedSize <= 0 || spacingInches <= 0) {
    return -1
  }
  const spacingFeet = spacingInches / 12
  const areaPerPlant = spacingFeet * spacingFeet
  return Math.floor(bedSize / areaPerPlant)
}
